import type { Rect, SceneId } from "./gameTypes.js";
import data from "./villageInteriors.json" with { type: "json" };
// Emberbrook Village house interiors (generated by
// scripts/build-village-interiors.mjs). Like the main house, heroes enter and
// leave individually; partners may be in different rooms.
export type VillageInterior = keyof typeof data;
export interface VillageInteriorDefinition {
  name: string;
  outsideScene?: SceneId;
  width: number;
  height: number;
  cameraBounds: Rect;
  spawn: { x: number; y: number };
  /** Doorway marker inside, where E leads back outside. */
  leave: { x: number; y: number };
  doorInteractionBounds: Rect;
  /** The house's door on the village map, and where heroes reappear. */
  door: { x: number; y: number };
  outside: { x: number; y: number };
  solids: Rect[];
}
export const villageInteriors = data as Record<
  VillageInterior,
  VillageInteriorDefinition
>;
export const villageInteriorIds = Object.keys(
  villageInteriors,
) as VillageInterior[];
export function isVillageInterior(id: SceneId): id is VillageInterior {
  return Object.hasOwn(villageInteriors, id);
}
/** Village map point naming the door of each house, e.g. door_cottage. */
export const villageDoorPoint = (id: VillageInterior) =>
  `door_${id.replace("VILLAGE_", "").toLowerCase()}`;
